return items.map(({ json }) => {
  const daysLate = Number(json.days_late || 0);
  const tenantName = json.tenant_name || 'Tenant';
  const dueDate = json.dueDate || '';
  const amount = json.amount ?? '';

  const reminderLevel = daysLate >= 8 ? 'final' : daysLate >= 4 ? 'firm' : 'friendly';
  const emailSubject = daysLate >= 8
    ? 'Final warning: your rent payment is overdue'
    : daysLate >= 4
      ? 'Urgent reminder: rent payment overdue'
      : 'Friendly reminder: rent payment overdue';

  const emailMessage = daysLate >= 8
    ? `<p>Dear ${tenantName},</p><p>This is a final warning that your rent payment of <strong>${amount} DT</strong> was due on <strong>${dueDate}</strong>.</p><p>Your payment is now <strong>${daysLate}</strong> days late. Please pay immediately to avoid further action.</p><p>Thank you.</p>`
    : daysLate >= 4
      ? `<p>Dear ${tenantName},</p><p>This is an urgent reminder that your rent payment of <strong>${amount} DT</strong> was due on <strong>${dueDate}</strong>.</p><p>Your payment is now <strong>${daysLate}</strong> days late. Please complete payment as soon as possible.</p><p>Thank you.</p>`
      : `<p>Dear ${tenantName},</p><p>This is a friendly reminder that your rent payment of <strong>${amount} DT</strong> was due on <strong>${dueDate}</strong>.</p><p>Your payment is now <strong>${daysLate}</strong> day(s) late.</p><p>Please complete payment when possible.</p><p>Thank you.</p>`;

  return {
    json: {
      ...json,
      reminder_level: reminderLevel,
      email_subject: emailSubject,
      email_message: emailMessage,
    },
  };
});
